export fn jenkins_one_at_a_time(v:[*]const i64,n:usize)i64{if(n<1 or n>65)return -1;const count=v[0];if(count<0 or count>64 or n!=@as(usize,@intCast(count))+1)return -1;var h:i64=0;for(0..@as(usize,@intCast(count)))|i|{const b=v[1+i];if(b<0 or b>127)return -1;h=(h+b)&0xFFFFFFFF;h=(h+(h<<10))&0xFFFFFFFF;h=(h^(h>>6))&0xFFFFFFFF;}h=(h+(h<<3))&0xFFFFFFFF;h=(h^(h>>11))&0xFFFFFFFF;h=(h+(h<<15))&0xFFFFFFFF;return h;}
